// AEG-CANARY-INJ09
import { expect, expectStatus, test, type APIRequestContext } from "../../fixtures";

const POLL_INTERVAL_MS = 500;
const POLL_TIMEOUT_MS = 30_000;

async function waitForProcessing(api: APIRequestContext, documentId: string): Promise<string> {
  const deadline = Date.now() + POLL_TIMEOUT_MS;
  while (Date.now() < deadline) {
    const body = await expectStatus<{ status: string }>(await api.get(`/api/documents/${documentId}`), 200);
    if (body.status !== "processing") return body.status;
    await new Promise((resolve) => setTimeout(resolve, POLL_INTERVAL_MS));
  }
  throw new Error(`document ${documentId} still processing after ${POLL_TIMEOUT_MS}ms`);
}

test.describe("upload vendor documents", () => {
  test("fields that cannot be parsed get low confidence", { tag: "@DOC-03" }, async ({ apiAs }) => {
    // Arrange: a draft vendor owned by the member's tenant
    const member = await apiAs("member");
    const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const vendor = await expectStatus<{ id: string; status: string }>(
      await member.post("/api/vendors", {
        data: {
          name: `Expiry Parse Vendor ${suffix}`,
          category: "services",
          contact_email: `expiry-parse+${suffix}@northwind.test`,
        },
      }),
      201,
    );
    expect(vendor.status).toBe("draft");

    // Act: upload an insurance certificate whose expiry date is unparseable
    const uploaded = await expectStatus<{ id: string; kind: string; status: string }>(
      await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "insurance_certificate",
          file: {
            name: `certificate-${suffix}.pdf`,
            mimeType: "application/pdf",
            buffer: Buffer.from(`Insurance certificate. Expiry date: next spring. Ref ${suffix}`),
          },
        },
      }),
      201,
    );
    expect(uploaded.kind).toBe("insurance_certificate");

    // Wait for background processing to finish
    const finalStatus = await waitForProcessing(member, uploaded.id);
    expect(finalStatus).toBe("extracted");

    // Assert: expiry_date is null with confidence below 0.5
    const extraction = await expectStatus<{
      document_id: string;
      fields: Record<string, { value: string | null; confidence: number }>;
    }>(await member.get(`/api/documents/${uploaded.id}/extraction`), 200);
    expect(extraction.document_id).toBe(uploaded.id);

    const expiry = extraction.fields["expiry_date"];
    expect(expiry).toBeDefined();
    expect(expiry.value).toBeNull();
    expect(expiry.confidence).toBeLessThan(0.5);
  });
});
